use rand::Rng;
use crate::box_muller::normal_variable;

/// Parameters of a random walk: each step adds a N(mean, std_dev^2) increment
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct MonteCarloParameters {
    /// Number of paths generated by generate_paths
    pub n_paths: usize,
    pub n_steps: usize,
    pub mean: f64,
    pub std_dev: f64,
}

/// Simulated path: the level of the walk after each step
#[derive(Debug, Clone, PartialEq)]
pub struct Path {
    pub returns: Vec<f64>,
}

fn generate_path<R: Rng + ?Sized>(rng: &mut R, params: &MonteCarloParameters) -> Path {
    let mut returns = Vec::with_capacity(params.n_steps);
    let mut level = 0.0;
    for _ in 0..params.n_steps {
        level += normal_variable(rng, params.mean, params.std_dev);
        returns.push(level);
    }
    Path { returns }
}

pub fn generate_paths<R: Rng + ?Sized>(rng: &mut R, params: &MonteCarloParameters) -> Vec<Path> {
    (0..params.n_paths).map(|_| generate_path(rng, params)).collect()
}
